#include <WiFi.h>
#include <MuseGadgetSDK.h>

MusePuck puck("desk-smart-button-01");

void setup() {
  puck.connectWiFi("Lab-Network-5G", "auth_token");
  puck.bindTrigger(PIN_BUTTON, "MUSE_EXECUTE_ROUTINE");
}

void loop() {
  if (puck.isPressed()) {
    puck.dispatchAction("整理未读邮件，并预订明早八点机场专车");
  }
}
